//! Port of `options.hpp` and `options.cpp`.
//!
//! The option table is generated by the `options!` macro from the same
//! list as the C++ `OPTIONS` macro (name, default, low, high, 'O'
//! (optimizable), 'P' (preprocessing), 'R' (resettable), usage).  `LOGOPT`
//! options (`log`, `logsort`) only exist with the `logging` feature.  The
//! option values are plain `i32` fields of [`Options`], accessed as
//! `opts.restart` etc. as in C++.

use std::sync::atomic::{AtomicI32, Ordering::Relaxed};

use crate::internal::Internal;
use crate::terminal::tout;
use crate::util::parse_int_str;

/// `struct Option` (renamed to avoid clashing with `std::option::Option`).
#[derive(Clone, Copy, Debug)]
pub struct Opt {
    pub name: &'static str,
    pub def: i32,
    pub lo: i32,
    pub hi: i32,
    pub optimizable: i32,
    pub preprocessing: bool,
    pub description: &'static str,
}

impl Opt {
    /// Position of this option in the table.
    #[inline]
    pub fn index(&self) -> usize {
        let base = Options::table().as_ptr() as usize;
        let me = self as *const Opt as usize;
        debug_assert!(me >= base);
        (me - base) / std::mem::size_of::<Opt>()
    }
    /// `int &Option::val (Options *)`.
    #[inline]
    pub fn val<'a>(&self, opts: &'a mut Options) -> &'a mut i32 {
        opts.val(self.index())
    }
}

/// For library usage we disable reporting by default while for the stand
/// alone SAT solver we enable it by default (`Options::reportdefault`).
static REPORTDEFAULT: AtomicI32 = AtomicI32::new(0);

/// Maps an option default token to its value (`(int) V`).
macro_rules! option_value {
    ($v:expr) => {
        ($v) as i32
    };
}

macro_rules! options {
    ($rd:ident; $(($n:ident, $v:expr, $l:expr, $h:expr, $o:expr, $p:expr, $r:expr, $d:literal, [$($cfg:tt)*])),* $(,)?) => {

        /// Number of options (`number_of_options`).
        pub const NUMBER_OF_OPTIONS: usize = 0 $(+ if cfg!($($cfg)*) { 1 } else { 0 })*;

        const fn build_table($rd: i32) -> [Opt; NUMBER_OF_OPTIONS] {
            let _ = $rd;
            [
                $(
                    #[cfg($($cfg)*)]
                    Opt {
                        name: stringify!($n),
                        def: option_value!($v),
                        lo: option_value!($l),
                        hi: option_value!($h),
                        optimizable: $o,
                        preprocessing: $p != 0,
                        description: $d,
                    },
                )*
            ]
        }

        /// The run-time option values.
        #[derive(Clone, Debug)]
        pub struct Options {
            pub internal: *mut Internal,
            $(
                #[cfg($($cfg)*)]
                pub $n: i32,
            )*
        }

        impl Options {
            /// `inline int &val (size_t idx)`.
            pub fn val(&mut self, idx: usize) -> &mut i32 {
                debug_assert!(idx < NUMBER_OF_OPTIONS);
                let mut i = 0usize;
                $(
                    #[cfg($($cfg)*)]
                    {
                        if i == idx {
                            return &mut self.$n;
                        }
                        i += 1;
                    }
                )*
                let _ = i;
                unreachable!("invalid option index {}", idx)
            }

            /// Initialize all the options to their default value 'V'.
            pub fn new(internal: *mut Internal) -> Options {
                let $rd = Options::reportdefault();
                // SAFETY: the table is reinitialized with the same values
                // (except 'reportdefault') as in C++.
                unsafe {
                    TABLE = build_table($rd);
                }
                let mut opts = Options {
                    internal,
                    $(
                        #[cfg($($cfg)*)]
                        $n: 0,
                    )*
                };
                // First initialize them according to defaults in 'options.hpp'.
                let mut prev: &str = "";
                $(
                    #[cfg($($cfg)*)]
                    {
                        if option_value!($l) > option_value!($v) {
                            fatal!(
                                "'{}' default '{}' lower minimum '{}' in 'options.hpp'",
                                stringify!($n), stringify!($v), stringify!($l)
                            );
                        }
                        if option_value!($h) < option_value!($v) {
                            fatal!(
                                "'{}' default '{}' larger maximum '{}' in 'options.hpp'",
                                stringify!($n), stringify!($v), stringify!($h)
                            );
                        }
                        if prev > stringify!($n) {
                            fatal!("'{}' ordered before '{}' in 'options.hpp'", prev, stringify!($n));
                        }
                        opts.$n = option_value!($v);
                        prev = stringify!($n);
                    }
                )*
                let _ = prev;

                // Check consistency in debugging mode.
                debug_assert!(Options::has("aaaaa").is_none());
                debug_assert!(Options::has("non-existing-option").is_none());
                debug_assert!(Options::has("zzzzz").is_none());

                // Now overwrite default options with environment values.
                $(
                    #[cfg($($cfg)*)]
                    Options::initialize_from_environment(
                        &mut opts.$n,
                        stringify!($n),
                        option_value!($l),
                        option_value!($h),
                    );
                )*
                opts
            }

            /// Print current values in command line form.
            pub fn print(&self) {
                let $rd = Options::reportdefault();
                let _ = $rd;
                let mut different: u32 = 0;
                let verbose = self.verbose;
                $(
                    #[cfg($($cfg)*)]
                    {
                        let n = self.$n;
                        let v = option_value!($v);
                        if n != v {
                            different += 1;
                        }
                        if verbose != 0 || n != v {
                            if option_value!($l) == 0 && option_value!($h) == 1 {
                                let buffer = format!(
                                    "--{}={}",
                                    stringify!($n),
                                    if n != 0 { "true" } else { "false" }
                                );
                                self.msg(format_args!(
                                    "  {}{:<30}{} ({} default {}'{}'{})",
                                    if n == v { "" } else { tout().bright_yellow_code() },
                                    buffer,
                                    if n == v { "" } else { tout().normal_code() },
                                    if n == v { "same as" } else { "different from" },
                                    if n == v { tout().green_code() } else { tout().yellow_code() },
                                    if v != 0 { "true" } else { "false" },
                                    tout().normal_code()
                                ));
                            } else {
                                let buffer = format!("--{}={}", stringify!($n), n);
                                self.msg(format_args!(
                                    "  {}{:<30}{} ({} default {}'{}'{})",
                                    if n == v { "" } else { tout().bright_yellow_code() },
                                    buffer,
                                    if n == v { "" } else { tout().normal_code() },
                                    if n == v { "same as" } else { "different from" },
                                    if n == v { tout().green_code() } else { tout().yellow_code() },
                                    stringify!($v),
                                    tout().normal_code()
                                ));
                            }
                        }
                    }
                )*
                if different == 0 {
                    self.msg(format_args!("all options are set to their default value"));
                }
            }

            /// Print usage message for all options.
            pub fn usage() {
                let $rd = Options::reportdefault();
                let _ = $rd;
                $(
                    #[cfg($($cfg)*)]
                    {
                        if option_value!($l) == 0 && option_value!($h) == 1 {
                            cprintf!(
                                "  {:<26} {} [{}]\n",
                                concat!("--", stringify!($n), "=bool"),
                                $d,
                                if option_value!($v) != 0 { "true" } else { "false" }
                            );
                        } else {
                            cprintf!(
                                "  {:<26} {} [{}]\n",
                                concat!("--", stringify!($n), "=", stringify!($l), "..", stringify!($h)),
                                $d,
                                stringify!($v)
                            );
                        }
                    }
                )*
            }

            /// Increase some limits (val=0..31).
            pub fn optimize(&mut self, mut val: i32) {
                let $rd = Options::reportdefault();
                let _ = $rd;
                if val < 0 {
                    self.log(format_args!("ignoring negative optimization mode '{}'", val));
                    return;
                }
                let max_val = 31;
                if val > max_val {
                    self.log(format_args!("optimization argument '{}' reduced to '{}'", val, max_val));
                    val = max_val;
                }
                let mut factor2: i64 = 1;
                let mut i = 0;
                while i < val && factor2 <= i32::MAX as i64 {
                    factor2 *= 2;
                    i += 1;
                }
                let mut factor10: i64 = 1;
                let mut i = 0;
                while i < val && factor10 <= i32::MAX as i64 {
                    factor10 *= 10;
                    i += 1;
                }
                let mut increased: u32 = 0;
                $(
                    #[cfg($($cfg)*)]
                    'opt: {
                        let o: i32 = $o;
                        if o == 0 {
                            break 'opt;
                        }
                        let factor1: i64 = if o == 1 { factor2 } else { factor10 };
                        let mut new_val: i64 = factor1 * (option_value!($v) as i64);
                        if new_val > option_value!($h) as i64 {
                            new_val = option_value!($h) as i64;
                        }
                        if new_val == option_value!($v) as i64 {
                            break 'opt;
                        }
                        self.log(format_args!(
                            "optimization mode '{}' for '{}' gives '{}' instead of '{}",
                            val, stringify!($n), new_val, option_value!($v)
                        ));
                        debug_assert!(new_val <= i32::MAX as i64);
                        self.$n = new_val as i32;
                        increased += 1;
                    }
                )*
                if increased != 0 {
                    self.msg(format_args!(
                        "optimization mode '-O{}' increased {} limits",
                        val, increased
                    ));
                }
            }

            /// Used by `Config` for the 'plain' configuration.
            pub fn disable_preprocessing(&mut self) {
                let mut count: usize = 0;
                $(
                    #[cfg($($cfg)*)]
                    'opt: {
                        if $p == 0 {
                            break 'opt;
                        }
                        if self.$n == 0 {
                            break 'opt;
                        }
                        self.log(format_args!("plain mode disables '{}'", stringify!($n)));
                        debug_assert!(option_value!($l) == 0);
                        debug_assert!(option_value!($h) == 1);
                        count += 1;
                        self.$n = 0;
                    }
                )*
                self.log(format_args!("forced plain mode disabled {} preprocessing options", count));
                let _ = count;
            }

            /// Used by `Config` for the 'default' configuration.
            pub fn reset_default_values(&mut self) {
                let $rd = Options::reportdefault();
                let _ = $rd;
                let mut count: usize = 0;
                $(
                    #[cfg($($cfg)*)]
                    'opt: {
                        if $r == 0 {
                            break 'opt;
                        }
                        if self.$n == option_value!($v) {
                            break 'opt;
                        }
                        self.log(format_args!(
                            "resetting option '{}' to default {}",
                            stringify!($n), stringify!($v)
                        ));
                        count += 1;
                        self.$n = option_value!($v);
                    }
                )*
                self.log(format_args!("reset {} options to their default values", count));
                let _ = count;
            }

            /// Copy 'self' into 'other'.
            pub fn copy(&self, other: &mut Options) {
                let $rd = Options::reportdefault();
                let _ = $rd;
                $(
                    #[cfg($($cfg)*)]
                    {
                        if self.$n == option_value!($v) {
                            other.log(format_args!(
                                "keeping non default option '--{}={}'",
                                stringify!($n), stringify!($v)
                            ));
                        } else {
                            other.log(format_args!(
                                "overwriting default option by '--{}={}'",
                                stringify!($n), self.$n
                            ));
                            other.$n = self.$n;
                        }
                    }
                )*
            }
        }
    };
}

