impl Options {
    /// `Options::reportdefault` (static).
    #[inline]
    pub fn reportdefault() -> i32 {
        REPORTDEFAULT.load(Relaxed)
    }

    /// Set `Options::reportdefault` (must happen before creating solvers).
    #[inline]
    pub fn set_reportdefault(v: i32) {
        REPORTDEFAULT.store(v, Relaxed)
    }

    /// The static option table (`Options::begin ()` .. `Options::end ()`).
    #[inline]
    pub fn table() -> &'static [Opt] {
        // SAFETY: only rewritten (with identical content modulo
        // 'reportdefault') in 'Options::new'.
        unsafe { &*std::ptr::addr_of!(TABLE) }
    }

    /// `Options::begin ()` / `end ()` as an iterator.
    #[inline]
    pub fn iter() -> std::slice::Iter<'static, Opt> {
        Options::table().iter()
    }

    #[inline]
    fn internal_ref(&self) -> Option<&Internal> {
        if self.internal.is_null() {
            None
        } else {
            // SAFETY: 'internal' points to the owning 'Internal'.
            Some(unsafe { &*self.internal })
        }
    }

    /// `MSG` through the owning 'Internal' (if any).
    fn msg(&self, args: std::fmt::Arguments<'_>) {
        if let Some(internal) = self.internal_ref() {
            internal.message(args);
        }
    }

    /// `LOG` through the owning 'Internal' (if any).
    #[allow(unused_variables)]
    fn log(&self, args: std::fmt::Arguments<'_>) {
        #[cfg(feature = "logging")]
        if let Some(internal) = self.internal_ref() {
            if internal.opts.log != 0 {
                crate::logging::Logger::log(internal, args);
            }
        }
    }

    /// Binary search in 'table', which requires option names to be sorted,
    /// which in turn is checked at start-up in 'Options::new'.
    pub fn has(name: &str) -> Option<&'static Opt> {
        let table = Options::table();
        let (mut l, mut r) = (0usize, NUMBER_OF_OPTIONS);
        while l < r {
            let m = l + (r - l) / 2;
            let res = &table[m];
            match name.cmp(res.name) {
                std::cmp::Ordering::Equal => return Some(res),
                std::cmp::Ordering::Less => r = m,
                std::cmp::Ordering::Greater => l = m + 1,
            }
        }
        None
    }

    /// Parse long option argument
    ///
    /// ```text
    ///   --<name>
    ///   --<name>=<val>
    ///   --no-<name>
    /// ```
    ///
    /// If parsing succeeds, 'true' is returned and the string will be set
    /// to the name of the option.  Additionally the parsed value is set.
    pub fn parse_long_option(arg: &str, name: &mut String, val: &mut i32) -> bool {
        let a = arg.as_bytes();
        let at = |i: usize| if i < a.len() { a[i] } else { 0 };
        if at(0) != b'-' || at(1) != b'-' {
            return false;
        }
        let has_no_prefix = at(2) == b'n' && at(3) == b'o' && at(4) == b'-';
        let offset = if has_no_prefix { 5 } else { 2 };
        let rest = if offset <= arg.len() { &arg[offset..] } else { "" };
        let pos = rest.find('=');
        *name = match pos {
            Some(p) => rest[..p].to_string(),
            None => rest.to_string(),
        };
        if Options::has(name).is_none() {
            return false;
        }
        match pos {
            None => *val = (!has_no_prefix) as i32,
            Some(p) => {
                let val_str = &rest[p + 1..];
                if !parse_int_str(val_str, val) {
                    return false;
                }
            }
        }
        true
    }

    fn initialize_from_environment(val: &mut i32, name: &str, l: i32, h: i32) {
        let key = format!("CADICAL_{}", name.to_ascii_uppercase());
        let val_str = match std::env::var(&key) {
            Ok(s) => s,
            Err(_) => return,
        };
        if !parse_int_str(&val_str, val) {
            return;
        }
        if *val < l {
            *val = l;
        }
        if *val > h {
            *val = h;
        }
    }

    /// Force to `[lo,hi]` interval (C++ overload `set (Option *, int)`,
    /// the option is given by its table index).
    pub fn set_option(&mut self, idx: usize, mut new_val: i32) {
        let o = &Options::table()[idx];
        let old_val = *self.val(idx);
        if old_val == new_val {
            self.log(format_args!("keeping value '{}' of option '{}'", old_val, o.name));
            return;
        }
        if new_val < o.lo {
            self.log(format_args!(
                "bounding '{}' to lower limit '{}' for option '{}'",
                new_val, o.lo, o.name
            ));
            new_val = o.lo;
        }
        if new_val > o.hi {
            self.log(format_args!(
                "bounding '{}' to upper limit '{}' for option '{}'",
                new_val, o.hi, o.name
            ));
            new_val = o.hi;
        }
        *self.val(idx) = new_val;
        self.log(format_args!(
            "set option 'set (\"{}\", {})' from '{}'",
            o.name, new_val, old_val
        ));
    }

    /// Explicit option value setting.
    pub fn set(&mut self, name: &str, val: i32) -> bool {
        match Options::has(name) {
            None => false,
            Some(o) => {
                self.set_option(o.index(), val);
                true
            }
        }
    }

    /// Get current value.
    pub fn get(&mut self, name: &str) -> i32 {
        match Options::has(name) {
            Some(o) => *self.val(o.index()),
            None => 0,
        }
    }

    pub fn is_preprocessing_option(name: &str) -> bool {
        match Options::has(name) {
            Some(o) => o.preprocessing,
            None => false,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn table_is_sorted_and_found() {
        let mut opts = Options::new(std::ptr::null_mut());
        assert_eq!(Options::table().len(), NUMBER_OF_OPTIONS);
        for w in Options::table().windows(2) {
            assert!(w[0].name < w[1].name);
        }
        let o = Options::has("reducetarget").unwrap();
        assert_eq!(o.def, 75);
        assert_eq!(*o.val(&mut opts), 75);
        assert!(opts.set("reducetarget", 1000));
        assert_eq!(opts.reducetarget, 100);
        assert_eq!(opts.get("elimboundmax"), 16);
        let mut name = String::new();
        let mut val = 0;
        assert!(Options::parse_long_option("--no-elim", &mut name, &mut val));
        assert_eq!((name.as_str(), val), ("elim", 0));
        assert!(Options::parse_long_option("--seed=1e3", &mut name, &mut val));
        assert_eq!((name.as_str(), val), ("seed", 1000));
        assert!(Options::has("log").is_some() == cfg!(feature = "logging"));
    }
}
